CREATE TABLE kk_stock_reservations(order_no TEXT NOT NULL,product_id INTEGER NOT NULL,quantity INTEGER NOT NULL CHECK(quantity>0),debited INTEGER NOT NULL,PRIMARY KEY(order_no,product_id));
--> statement-breakpoint
CREATE TRIGGER kk_stock_reserve BEFORE INSERT ON kk_stock_reservations BEGIN SELECT RAISE(ABORT,'STOCK_CHANGED') WHERE NOT EXISTS(SELECT 1 FROM products WHERE id=NEW.product_id AND status='active') OR (SELECT CAST(json_extract(commerce_json,'$.stock') AS INTEGER) FROM products WHERE id=NEW.product_id)>=0 AND (SELECT CAST(json_extract(commerce_json,'$.stock') AS INTEGER) FROM products WHERE id=NEW.product_id)<NEW.quantity; UPDATE products SET commerce_json=json_set(commerce_json,'$.stock',json_extract(commerce_json,'$.stock')-NEW.quantity) WHERE id=NEW.product_id AND json_extract(commerce_json,'$.stock')>=0; END;
--> statement-breakpoint
CREATE TRIGGER kk_payment_accrual AFTER UPDATE OF paid_at ON shopping_requests WHEN OLD.paid_at IS NULL AND NEW.paid_at IS NOT NULL AND NEW.member_id IS NOT NULL AND NEW.pricing_json IS NOT NULL BEGIN INSERT INTO kk_ledger(event_key,member_id,order_id,miles,spend_jpy,spend_krw,reason,debt_delta) SELECT 'payment:'||NEW.id,id,NEW.id, MAX(0,CAST(json_extract(NEW.pricing_json,'$.goodsJpy') / iif(json_extract(NEW.pricing_json,'$.items[0].sourceCurrency')='KRW',5000,500) AS INTEGER)-miles_debt), iif(json_extract(NEW.pricing_json,'$.items[0].sourceCurrency')='KRW',0,json_extract(NEW.pricing_json,'$.goodsJpy')), iif(json_extract(NEW.pricing_json,'$.items[0].sourceCurrency')='KRW',json_extract(NEW.pricing_json,'$.goodsJpy'),0), '付款消費 / Paid purchase', -MIN(miles_debt,CAST(json_extract(NEW.pricing_json,'$.goodsJpy') / iif(json_extract(NEW.pricing_json,'$.items[0].sourceCurrency')='KRW',5000,500) AS INTEGER)) FROM kk_members WHERE id=NEW.member_id AND NOT EXISTS(SELECT 1 FROM kk_ledger WHERE event_key='payment:'||NEW.id); UPDATE kk_members SET miles=miles+(SELECT miles FROM kk_ledger WHERE event_key='payment:'||NEW.id), miles_debt=miles_debt+(SELECT debt_delta FROM kk_ledger WHERE event_key='payment:'||NEW.id), spend_jpy=spend_jpy+(SELECT spend_jpy FROM kk_ledger WHERE event_key='payment:'||NEW.id), spend_krw=spend_krw+(SELECT spend_krw FROM kk_ledger WHERE event_key='payment:'||NEW.id) WHERE id=NEW.member_id AND changes()=1; END;
--> statement-breakpoint
CREATE TRIGGER kk_snack_redemption AFTER UPDATE OF snack_redeemed ON shopping_requests WHEN OLD.snack_redeemed=0 AND NEW.snack_redeemed=1 BEGIN SELECT RAISE(ABORT,'POINTS_CHANGED') WHERE COALESCE((SELECT miles FROM kk_members WHERE id=NEW.member_id),0)<30; INSERT INTO kk_ledger(event_key,member_id,order_id,miles,reason) VALUES('snack:'||NEW.id,NEW.member_id,NEW.id,-30,'韓國小包零食 / Korean snack pouch'); UPDATE kk_members SET miles=miles-30 WHERE id=NEW.member_id; END;
